/**
 * What a person reads: the file's own name.
 */
name: string, kind: AttachmentKind,
/**
 * Bytes, for a file; `null` for a folder, or a pipe or device.
 */
size: number | null,
/**
 * Where known: the type a put was given, or the one the extension names.
 */
